void ADukeCharacter::ApplyDef(const FDukeCharacterDef* Def, const FLinearColor& Tint)
{
	if (Def)
	{
		DefId = Def->Id; DisplayName = Def->Name; Role = Def->Role; Lines = Def->Lines;
	}
	USkeletalMesh* Skel = (Def && !Def->Mesh.IsEmpty()) ? LoadObject<USkeletalMesh>(nullptr, *Def->Mesh) : nullptr;
	if (Skel)
	{
		GetMesh()->SetSkeletalMeshAsset(Skel);
		const float H = Skel->GetBounds().BoxExtent.Z * 2.f;
		const float Want = FMath::Clamp(Def->Height, 1.2f, 2.3f) * 100.f;
		const float Scale = H > 1.f ? Want / H : 1.f;
		GetMesh()->SetRelativeScale3D(FVector(Scale));
		GetMesh()->SetRelativeLocation(FVector(0.f, 0.f, -GetCapsuleComponent()->GetScaledCapsuleHalfHeight()));
		GetMesh()->SetRelativeRotation(FRotator(0.f, Def->MeshYaw, 0.f));
		GetMesh()->SetVisibility(true);
		Proxy->SetVisibility(false);
		Anims.Empty();
		for (const TPair<FString, FString>& A : Def->Anims)
			if (UAnimSequence* Seq = LoadObject<UAnimSequence>(nullptr, *A.Value)) Anims.Add(A.Key, Seq);
		// find a right-hand bone for weapons
		HandBone = NAME_None;
		for (int32 i = 0; i < GetMesh()->GetNumBones(); ++i)
		{
			const FString B = GetMesh()->GetBoneName(i).ToString().ToLower();
			if (B.Contains(TEXT("righthand")) || B == TEXT("hand_r") || B.EndsWith(TEXT("r_hand")) || (B.Contains(TEXT("hand")) && (B.Contains(TEXT("right")) || B.EndsWith(TEXT("_r")))))
			{
				HandBone = GetMesh()->GetBoneName(i);
				break;
			}
		}
		CurAnim.Empty();
	}
	else
	{
		Proxy->SetVisibility(true);
		if (UMaterialInterface* Base = Proxy->GetMaterial(0))
		{
			UMaterialInstanceDynamic* MID = UMaterialInstanceDynamic::Create(Base, this);
			MID->SetVectorParameterValue(TEXT("Color"), Tint);
			Proxy->SetMaterial(0, MID);
		}
	}
}

void ADukeCharacter::SetupPlayerInputComponent(UInputComponent* PIC)
{
	Super::SetupPlayerInputComponent(PIC);
	UEnhancedInputComponent* EIC = Cast<UEnhancedInputComponent>(PIC);
	if (!EIC) return;
	UDukeInput* In = UDukeInput::Get();
	EIC->BindAction(In->Move, ETriggerEvent::Triggered, this, &ADukeCharacter::OnMove);
	EIC->BindAction(In->Look, ETriggerEvent::Triggered, this, &ADukeCharacter::OnLook);
	EIC->BindAction(In->Jump, ETriggerEvent::Started, this, &ADukeCharacter::OnJumpStart);
	EIC->BindAction(In->Jump, ETriggerEvent::Completed, this, &ADukeCharacter::OnJumpStop);
	EIC->BindAction(In->Sprint, ETriggerEvent::Started, this, &ADukeCharacter::OnSprint);
	EIC->BindAction(In->Sprint, ETriggerEvent::Completed, this, &ADukeCharacter::OnSprintStop);
	EIC->BindAction(In->Fire, ETriggerEvent::Started, this, &ADukeCharacter::OnFire);
	EIC->BindAction(In->Fire, ETriggerEvent::Completed, this, &ADukeCharacter::OnFireStop);
	EIC->BindAction(In->Aim, ETriggerEvent::Started, this, &ADukeCharacter::OnAim);
	EIC->BindAction(In->Aim, ETriggerEvent::Completed, this, &ADukeCharacter::OnAimStop);
	EIC->BindAction(In->Vehicle, ETriggerEvent::Started, this, &ADukeCharacter::OnVehicle);
	EIC->BindAction(In->Talk, ETriggerEvent::Started, this, &ADukeCharacter::OnTalk);
	EIC->BindAction(In->Reload, ETriggerEvent::Started, this, &ADukeCharacter::OnReload);
	EIC->BindAction(In->NextWeapon, ETriggerEvent::Started, this, &ADukeCharacter::OnNextWeapon);
}

void ADukeCharacter::OnMove(const FInputActionValue& V)
{
	if (bDead || !Controller) return;
	const FVector2D A = V.Get<FVector2D>();
	const FRotator Yaw(0.f, Controller->GetControlRotation().Yaw, 0.f);
	AddMovementInput(FRotationMatrix(Yaw).GetUnitAxis(EAxis::X), A.Y);
	AddMovementInput(FRotationMatrix(Yaw).GetUnitAxis(EAxis::Y), A.X);
}
void ADukeCharacter::OnLook(const FInputActionValue& V)
{
	const FVector2D A = V.Get<FVector2D>();
	AddControllerYawInput(A.X);
	AddControllerPitchInput(-A.Y);
}
void ADukeCharacter::OnJumpStart(const FInputActionValue&) { if (!bDead) Jump(); }
void ADukeCharacter::OnJumpStop(const FInputActionValue&) { StopJumping(); }
void ADukeCharacter::OnSprint(const FInputActionValue&) { bSprinting = true; }
void ADukeCharacter::OnSprintStop(const FInputActionValue&) { bSprinting = false; }
void ADukeCharacter::OnFire(const FInputActionValue&) { bFiring = true; NextShot = FMath::Min(NextShot, GetWorld()->GetTimeSeconds()); }
void ADukeCharacter::OnFireStop(const FInputActionValue&) { bFiring = false; }
void ADukeCharacter::OnAim(const FInputActionValue&) { bAiming = true; }
void ADukeCharacter::OnAimStop(const FInputActionValue&) { bAiming = false; }
void ADukeCharacter::OnReload(const FInputActionValue&) { TryReload(); }
void ADukeCharacter::OnNextWeapon(const FInputActionValue&)
{
	if (!Owned.Num()) return;
	EquipWeapon(Slot + 1 >= Owned.Num() ? -1 : Slot + 1);
}
void ADukeCharacter::OnVehicle(const FInputActionValue&)
{
	if (bDead) return;
	if (ADukeGameMode* GM = ADukeGameMode::Get(this))
		if (ADukeVehicle* V = GM->FindVehicleNear(GetActorLocation(), 450.f)) GM->EnterVehicle(this, V);
}
void ADukeCharacter::OnTalk(const FInputActionValue&)
{
	if (ADukeGameMode* GM = ADukeGameMode::Get(this)) GM->PlayerTalk(this);
}

void ADukeCharacter::GiveWeapon(int32 WeaponIndex, int32 Rounds)
{
	UDukeGameInstance* GI = Cast<UDukeGameInstance>(GetGameInstance());
	if (!GI || !GI->Weapons.IsValidIndex(WeaponIndex)) return;
	int32 S = Owned.Find(WeaponIndex);
	if (S == INDEX_NONE)
	{
		S = Owned.Add(WeaponIndex);
		Clip.Add(GI->Weapons[WeaponIndex].Magazine);
		Reserve.Add(0);
	}
	Reserve[S] += Rounds;
	if (Slot < 0) EquipWeapon(S);
}

void ADukeCharacter::EquipWeapon(int32 NewSlot)
{
	Slot = Owned.IsValidIndex(NewSlot) ? NewSlot : -1;
	UDukeGameInstance* GI = Cast<UDukeGameInstance>(GetGameInstance());
	if (Slot < 0 || !GI)
	{
		WeaponMesh->SetHiddenInGame(true);
		return;
	}
	const FDukeWeaponDef& W = GI->Weapons[Owned[Slot]];
	UStaticMesh* SM = W.Mesh.IsEmpty() ? nullptr : LoadObject<UStaticMesh>(nullptr, *W.Mesh);
	if (!SM) SM = LoadObject<UStaticMesh>(nullptr, TEXT("/Engine/BasicShapes/Cube.Cube"));
	WeaponMesh->SetStaticMesh(SM);
	if (SM)
	{
		const FVector Ext = SM->GetBounds().BoxExtent * 2.f;
		const float Longest = FMath::Max3(Ext.X, Ext.Y, Ext.Z);
		const float Scale = Longest > 0.1f ? (W.Length * 100.f) / Longest : 1.f;
		WeaponMesh->SetRelativeScale3D(W.Mesh.IsEmpty() ? FVector(W.Length, 0.05f, 0.12f) : FVector(Scale));
	}
	if (HandBone != NAME_None)
		WeaponMesh->AttachToComponent(GetMesh(), FAttachmentTransformRules::SnapToTargetNotIncludingScale, HandBone);
	else
	{
		WeaponMesh->AttachToComponent(RootComponent, FAttachmentTransformRules::KeepRelativeTransform);
		WeaponMesh->SetRelativeLocation(FVector(30.f, 25.f, 20.f));
	}
	WeaponMesh->SetRelativeRotation(FRotator(0.f, W.Yaw, 0.f));
	WeaponMesh->SetHiddenInGame(false);
}

void ADukeCharacter::TryReload()
{
	UDukeGameInstance* GI = Cast<UDukeGameInstance>(GetGameInstance());
	if (!GI || Slot < 0 || ReloadDone > GetWorld()->GetTimeSeconds()) return;
	const int32 Mag = GI->Weapons[Owned[Slot]].Magazine;
	const int32 Need = Mag - Clip[Slot];
	if (Need <= 0 || Reserve[Slot] <= 0) return;
	const int32 Take = FMath::Min(Need, Reserve[Slot]);
	Clip[Slot] += Take; Reserve[Slot] -= Take;
	ReloadDone = GetWorld()->GetTimeSeconds() + 1.4f;
}

bool ADukeCharacter::FireAt(const FVector& From, const FVector& Direction, float Spread)
{
	UDukeGameInstance* GI = Cast<UDukeGameInstance>(GetGameInstance());
	float Damage = 12.f, Range = 2.f; // fists
	int32 Pellets = 1;
	if (GI && Slot >= 0)
	{
		const FDukeWeaponDef& W = GI->Weapons[Owned[Slot]];
		Damage = W.Damage; Range = FMath::Max(5.f, W.Range * 2.f);
		if (W.Type == TEXT("Shotgun")) { Pellets = 6; Spread += 0.06f; Damage /= 3.f; }
		if (W.Type == TEXT("Melee")) Range = 2.2f;
	}
	FCollisionQueryParams Params(SCENE_QUERY_STAT(DukeShot), true, this);
	Params.AddIgnoredActor(this);
	bool bHitAny = false;
	for (int32 p = 0; p < Pellets; ++p)
	{
		const FVector Dir = FMath::VRandCone(Direction.GetSafeNormal(), Spread);
		const FVector End = From + Dir * Range * 100.f;
		FHitResult Hit;
		if (GetWorld()->LineTraceSingleByObjectType(Hit, From, End, FCollisionObjectQueryParams(FCollisionObjectQueryParams::AllObjects), Params))
		{
			if (AActor* A = Hit.GetActor())
			{
				UGameplayStatics::ApplyPointDamage(A, Damage, Dir, Hit, GetController(), this, UDamageType::StaticClass());
				if (Cast<APawn>(A)) { bHitAny = true; LastHitMarker = Hit.ImpactPoint; HitMarkerTime = GetWorld()->GetTimeSeconds(); }
			}
		}
	}
	LastShotTime = GetWorld()->GetTimeSeconds();
	if (Slot >= 0) { MuzzleLight->SetIntensity(9000.f); MuzzleOff = LastShotTime + 0.05f; }
	return bHitAny;
}

void ADukeCharacter::TickWeapon(float Dt)
{
	const float Now = GetWorld()->GetTimeSeconds();
	if (MuzzleOff > 0.f && Now > MuzzleOff) { MuzzleLight->SetIntensity(0.f); MuzzleOff = 0.f; }
	if (!bIsPlayer || !bFiring || bDead || Now < NextShot || Now < ReloadDone) return;
	UDukeGameInstance* GI = Cast<UDukeGameInstance>(GetGameInstance());
	if (!GI) return;
	bool bAuto = false;
	float Rpm = 150.f;
	if (Slot >= 0)
	{
		const FDukeWeaponDef& W = GI->Weapons[Owned[Slot]];
		if (Clip[Slot] <= 0) { TryReload(); return; }
		Clip[Slot]--;
		Rpm = W.Rpm;
		bAuto = W.Type == TEXT("SMG") || W.Type == TEXT("Assault rifle");
	}
	const FVector From = Camera->GetComponentLocation() + Camera->GetForwardVector() * (Boom->TargetArmLength + 20.f);
	const float Spread = FMath::DegreesToRadians(bAiming ? 0.6f : 2.5f) + (GetVelocity().Size() > 300.f ? 0.03f : 0.f);
	FireAt(From, Camera->GetForwardVector(), Spread);
	NextShot = Now + 60.f / Rpm;
	if (!bAuto) bFiring = false;
	if (Slot >= 0 && Clip[Slot] <= 0) TryReload();
}

float ADukeCharacter::TakeDamage(float Amount, FDamageEvent const& Event, AController* Inst, AActor* Causer)
{
	if (bDead) return 0.f;
	float Dmg = Super::TakeDamage(Amount, Event, Inst, Causer);
	if (Armor > 0.f) { const float Soak = FMath::Min(Armor, Dmg * 0.6f); Armor -= Soak; Dmg -= Soak; }
	Health -= Dmg;
	ADukeGameMode* GM = ADukeGameMode::Get(this);
	const bool bByPlayer = Inst && Inst->IsPlayerController();
	if (!bIsPlayer && bByPlayer && GM)
	{
		Threat = Inst->GetPawn();
		if (Mode == EDukeNpcMode::Civilian || Mode == EDukeNpcMode::Giver) { FleeUntil = GetWorld()->GetTimeSeconds() + 12.f; GM->ReportCrime(1, GetActorLocation()); }
		else if (Mode == EDukeNpcMode::Police) GM->ReportCrime(2, GetActorLocation());
	}
	if (Health <= 0.f) Die(Inst);
	return Dmg;
}

void ADukeCharacter::Die(AController* Killer)
{
	bDead = true;
	DeadTime = GetWorld()->GetTimeSeconds();
	bFiring = false;
	GetCharacterMovement()->DisableMovement();
	GetCapsuleComponent()->SetCollisionEnabled(ECollisionEnabled::NoCollision);
	if (GetMesh()->GetSkeletalMeshAsset() && GetMesh()->GetPhysicsAsset())
	{
		GetMesh()->SetCollisionProfileName(TEXT("Ragdoll"));
		GetMesh()->SetSimulatePhysics(true);
	}
	else if (TObjectPtr<UAnimSequence>* A = Anims.Find(TEXT("die")))
	{
		GetMesh()->PlayAnimation(*A, false);
	}
	else
	{
		Proxy->SetRelativeRotation(FRotator(90.f, 0.f, 0.f));
	}
	if (ADukeGameMode* GM = ADukeGameMode::Get(this)) GM->OnCharacterDied(this, Killer);
}

void ADukeCharacter::Respawn(const FVector& Where)
{
	bDead = false;
	Health = MaxHealth;
	SetActorLocation(Where + FVector(0.f, 0.f, 100.f), false, nullptr, ETeleportType::TeleportPhysics);
	GetCapsuleComponent()->SetCollisionEnabled(ECollisionEnabled::QueryAndPhysics);
	GetCharacterMovement()->SetMovementMode(MOVE_Walking);
	if (GetMesh()->IsSimulatingPhysics())
	{
		GetMesh()->SetSimulatePhysics(false);
		GetMesh()->SetCollisionProfileName(TEXT("CharacterMesh"));
		GetMesh()->AttachToComponent(GetCapsuleComponent(), FAttachmentTransformRules::SnapToTargetNotIncludingScale);
		GetMesh()->SetRelativeLocation(FVector(0.f, 0.f, -GetCapsuleComponent()->GetScaledCapsuleHalfHeight()));
		if (UDukeGameInstance* GI = Cast<UDukeGameInstance>(GetGameInstance()))
			if (const FDukeCharacterDef* D = GI->FindCharacter(DefId)) GetMesh()->SetRelativeRotation(FRotator(0.f, D->MeshYaw, 0.f));
	}
	Proxy->SetRelativeRotation(FRotator::ZeroRotator);
	CurAnim.Empty();
}

void ADukeCharacter::UpdateAnimation()
{
	if (!GetMesh()->GetSkeletalMeshAsset() || GetMesh()->IsSimulatingPhysics()) return;
	FString Want;
	const float Speed = GetVelocity().Size2D();
	const float Now = GetWorld()->GetTimeSeconds();
	if (bDead) Want = TEXT("die");
	else if (GetCharacterMovement()->IsFalling()) Want = TEXT("jump");
	else if (Speed > 330.f) Want = TEXT("run");
	else if (Speed > 25.f) Want = TEXT("walk");
	else if (Now - LastShotTime < 0.6f && Slot >= 0) Want = TEXT("shoot");
	else Want = TEXT("idle");
	if (!Anims.Contains(Want))
	{
		if (Want == TEXT("run") && Anims.Contains(TEXT("walk"))) Want = TEXT("walk");
		else if (Anims.Contains(TEXT("idle"))) Want = TEXT("idle");
		else return;
	}
	if (Want == CurAnim) return;
	CurAnim = Want;
	const bool bLoop = Want != TEXT("die") && Want != TEXT("jump") && Want != TEXT("shoot");
	GetMesh()->PlayAnimation(Anims[Want], bLoop);
}

FVector ADukeCharacter::CornerPos(int32 I, int32 J, int32 C) const
{
	const UDukeGameInstance* GI = Cast<UDukeGameInstance>(GetGameInstance());
	const float B = GI ? GI->BlockSize : 60.f;
	const float X0 = I * B + 9.f, X1 = (I + 1) * B - 9.f, Y0 = J * B + 9.f, Y1 = (J + 1) * B - 9.f;
	const float Xs[4] = { X0, X1, X1, X0 }, Ys[4] = { Y0, Y0, Y1, Y1 };
	return FVector(Xs[C & 3] * 100.f, Ys[C & 3] * 100.f, GetActorLocation().Z);
}

void ADukeCharacter::TickAI(float Dt)
{
	ADukeGameMode* GM = ADukeGameMode::Get(this);
	UDukeGameInstance* GI = Cast<UDukeGameInstance>(GetGameInstance());
	if (!GM || !GI || bDead) return;
	const float Now = GetWorld()->GetTimeSeconds();
	APawn* Player = UGameplayStatics::GetPlayerPawn(this, 0);
	const FVector Me = GetActorLocation();
	const float PDist = Player ? FVector::Dist2D(Player->GetActorLocation(), Me) : 1e9f;
	UCharacterMovementComponent* Move = GetCharacterMovement();

	const bool bCombatant = Mode == EDukeNpcMode::Police || Mode == EDukeNpcMode::Hostile || Mode == EDukeNpcMode::Target;
	const bool bEngage = Player && ((Mode == EDukeNpcMode::Police && GM->GetWanted() > 0) || ((Mode == EDukeNpcMode::Hostile || Mode == EDukeNpcMode::Target) && PDist < 4000.f));
	if (bCombatant && bEngage)
	{
		const FVector To = (Player->GetActorLocation() - Me).GetSafeNormal2D();
		SetActorRotation(FMath::RInterpTo(GetActorRotation(), To.Rotation(), Dt, 8.f));
		if (PDist > 1400.f) { Move->MaxWalkSpeed = 520.f; AddMovementInput(To, 1.f); }
		if (PDist < 3000.f && Now > NextShot)
		{
			FCollisionQueryParams P(SCENE_QUERY_STAT(DukeLOS), false, this);
			FHitResult H;
			const FVector Eye = Me + FVector(0, 0, 60);
			const bool bBlocked = GetWorld()->LineTraceSingleByChannel(H, Eye, Player->GetActorLocation(), ECC_Visibility, P) && H.GetActor() != Player;
			if (!bBlocked)
			{
				const float Spread = FMath::DegreesToRadians(2.f + PDist / 400.f);
				FireAt(Eye, Player->GetActorLocation() - Eye, Spread);
			}
			NextShot = Now + FMath::FRandRange(0.7f, 1.3f);
		}
		return;
	}
	if (Mode == EDukeNpcMode::Giver || Mode == EDukeNpcMode::Target || Mode == EDukeNpcMode::Hostile)
	{
		if (Player && PDist < 600.f)
			SetActorRotation(FMath::RInterpTo(GetActorRotation(), (Player->GetActorLocation() - Me).GetSafeNormal2D().Rotation(), Dt, 5.f));
		if (FVector::Dist2D(Me, HomeSpot) > 150.f) { Move->MaxWalkSpeed = 160.f; AddMovementInput((HomeSpot - Me).GetSafeNormal2D(), 1.f); }
		return;
	}
	// civilians (and off-duty police): flee or walk the sidewalk loop
	if (Now < FleeUntil && Threat.IsValid())
	{
		Move->MaxWalkSpeed = 560.f;
		AddMovementInput((Me - Threat->GetActorLocation()).GetSafeNormal2D(), 1.f);
		return;
	}
	if (bTalking) return;
	Move->MaxWalkSpeed = 150.f;
	FVector Target = CornerPos(NavI, NavJ, Corner);
	if (FVector::Dist2D(Target, Me) < 120.f)
	{
		if (FMath::FRand() < 0.25f)
		{
			// cross the street to the neighbouring block's matching corner
			static const int32 Xs[4][2] = { {-1,1},{1,0},{1,3},{-1,2} };
			static const int32 Ys[4][2] = { {-1,3},{-1,2},{1,1},{1,0} };
			const bool bX = FMath::RandBool();
			const int32 NI = NavI + (bX ? Xs[Corner][0] : 0), NJ = NavJ + (bX ? 0 : Ys[Corner][0]);
			if (NI >= 0 && NJ >= 0 && NI < GI->GridN && NJ < GI->GridN) { NavI = NI; NavJ = NJ; Corner = bX ? Xs[Corner][1] : Ys[Corner][1]; return; }
		}
		Corner = (Corner + CornerDir + 4) % 4;
		return;
	}
	if (Player && PDist < 110.f) return; // polite stop
	AddMovementInput((Target - Me).GetSafeNormal2D(), 1.f);
}

void ADukeCharacter::Tick(float Dt)
{
	Super::Tick(Dt);
	TickWeapon(Dt);
	if (bIsPlayer)
	{
		UCharacterMovementComponent* Move = GetCharacterMovement();
		Move->MaxWalkSpeed = bAiming ? 260.f : (bSprinting ? 760.f : 480.f);
		Move->bOrientRotationToMovement = !bAiming;
		bUseControllerRotationYaw = bAiming;
		Boom->TargetArmLength = FMath::FInterpTo(Boom->TargetArmLength, bAiming ? 170.f : 380.f, Dt, 10.f);
		Camera->FieldOfView = FMath::FInterpTo(Camera->FieldOfView, bAiming ? 62.f : 80.f, Dt, 10.f);
	}
	else if (!bDead)
	{
		TickAI(Dt);
	}
	UpdateAnimation();
}
